"""
Analyze a PDF to detect shaded/colored rectangular regions \(code blocks, command examples\).
Uses PyMuPDF \(fitz\) to inspect drawings, text blocks, and background formatting.
"""
import fitz
import json
import sys
from collections import defaultdict

PDF_PATH = r"c:\\Users\\endur\\Downloads\\tmaxjapan\\kms\\kms-docker-remote\\uploads\\manuals\\MVS_Openframe 7.1_v3.1.3_JP\\OF_HiDB_7.2_HiDB-Guide_v3.1.2_jp.pdf"

def color_to_hex\(color\):
    if color is None:
        return None
    if isinstance\(color, \(int, float\)\):
        v = int\(color * 255\)
        return f"#{v:02x}{v:02x}{v:02x}"
    try:
        return "#" + "".join\(f"{int\(c*255\):02x}" for c in color\)
    except:
        return str\(color\)

def get_text_in_rect\(page, rect_tuple\):
    r = fitz.Rect\(rect_tuple\)
    text = page.get_text\("text", clip=r\).strip\(\)
    return text

def analyze_page_drawings\(page\):
    drawings = page.get_drawings\(\)
    filled_rects = []
    for i, d in enumerate\(drawings\):
        fill = d.get\("fill"\)
        if fill is None:
            continue
        rect = d.get\("rect"\)
        if rect is None:
            continue
        r = fitz.Rect\(rect\)
        if r.width < 100 or r.height < 10:
            continue
        filled_rects.append\({
            "index": i,
            "rect": \(round\(r.x0,1\), round\(r.y0,1\), round\(r.x1,1\), round\(r.y1,1\)\),
            "width": round\(r.width,1\),
            "height": round\(r.height,1\),
            "fill_color": color_to_hex\(fill\),
            "stroke_color": color_to_hex\(d.get\("color"\)\),
            "fill_raw": fill,
        }\)
    return filled_rects

def analyze_text_blocks\(page\):
    blocks_info = []
    text_dict = page.get_text\("dict"\)
    for block in text_dict.get\("blocks", []\):
        if block["type"] == 0:
            bbox = block["bbox"]
            block_text = ""
            fonts_used = set\(\)
            colors_used = set\(\)
            sizes_used = set\(\)
            for line in block.get\("lines", []\):
                for span in line.get\("spans", []\):
                    block_text += span["text"]
                    fonts_used.add\(span.get\("font", ""\)\)
                    colors_used.add\(span.get\("color", 0\)\)
                    sizes_used.add\(round\(span.get\("size", 0\), 1\)\)
                block_text += "\\n"
            block_text = block_text.strip\(\)
            if block_text:
                blocks_info.append\({
                    "bbox": tuple\(round\(v,1\) for v in bbox\),
                    "text_preview": block_text[:150],
                    "fonts": list\(fonts_used\),
                    "text_colors": [f"#{c:06x}" if isinstance\(c,int\) else str\(c\) for c in colors_used],
                    "sizes": sorted\(sizes_used\),
                }\)
    return blocks_info

def analyze_rawdict_extra\(page\):
    raw = page.get_text\("rawdict"\)
    info = []
    for block in raw.get\("blocks", []\):
        if block["type"] == 0:
            interesting = set\(block.keys\(\)\) - {"type","bbox","lines","number"}
            for line in block.get\("lines", []\):
                for span in line.get\("spans", []\):
                    extra = set\(span.keys\(\)\) - {"text","font","size","color","flags","bbox","origin","ascender","descender","bidi_level","bidi_dir","chars"}
                    if extra:
                        interesting.update\(f"span.{k}" for k in extra\)
            if interesting:
                text = ""
                for line in block.get\("lines", []\):
                    for span in line.get\("spans", []\):
                        text += span["text"]
                info.append\({"bbox": block["bbox"], "extra_keys": list\(interesting\), "text_preview": text[:80]}\)
    return info

def main\(\):
    doc = fitz.open\(PDF_PATH\)
    print\(f"PDF: {PDF_PATH}"\)
    print\(f"Total pages: {len\(doc\)}"\)
