        page = doc[pn]
        text = page.get_text\("text"\)
        if "dbdcpybkgen" in text.lower\(\):
            target_pages.append\(pn\)
        if "使用例" in text:
            usage_pages.append\(pn\)

    print\(f"\\nPages with 'dbdcpybkgen': {[p+1 for p in target_pages]}"\)
    print\(f"Pages with '使用例': {[p+1 for p in usage_pages]} \(first 20: {[p+1 for p in usage_pages[:20]]}\)"\)

    # Scan all pages for filled rects
    print\("\\n" + "=" * 80\)
    print\("SCANNING ALL PAGES FOR FILLED RECTANGLES"\)
    print\("=" * 80\)
    pages_with_rects = {}
    for pn in range\(len\(doc\)\):
        page = doc[pn]
        rects = analyze_page_drawings\(page\)
        if rects:
            pages_with_rects[pn] = rects

    print\(f"\\nPages with filled rects \(w>100, h>10\): {len\(pages_with_rects\)} out of {len\(doc\)}"\)
    print\(f"Page numbers: {[p+1 for p in sorted\(pages_with_rects.keys\(\)\)[:30]]}..."\)

    color_counts = defaultdict\(int\)
    for pn, rects in pages_with_rects.items\(\):
        for r in rects:
            color_counts[r["fill_color"]] += 1
    print\("\\nFill color distribution:"\)
    for color, count in sorted\(color_counts.items\(\), key=lambda x: -x[1]\):
        print\(f"  {color}: {count} rectangles"\)

    # Detailed analysis of select pages
    pages_to_analyze = set\(target_pages[:3]\)
    for p in usage_pages:
        if p in pages_with_rects:
            pages_to_analyze.add\(p\)
            if len\(pages_to_analyze\) >= 6:
                break
    if len\(pages_to_analyze\) < 3:
        for p in sorted\(pages_with_rects.keys\(\)\):
            pages_to_analyze.add\(p\)
            if len\(pages_to_analyze\) >= 5:
                break

    print\("\\n" + "=" * 80\)
    print\(f"DETAILED ANALYSIS: {len\(pages_to_analyze\)} PAGES"\)
    print\("=" * 80\)

    for pn in sorted\(pages_to_analyze\):
        page = doc[pn]
        text = page.get_text\("text"\)

        print\(f"\\n{'─'*80}"\)
        print\(f"PAGE {pn+1}"\)
        print\(f"{'─'*80}"\)
        print\(f"Text preview: {text[:250].strip\(\)}"\)
        print\(\)

        rects = pages_with_rects.get\(pn, []\)
        if rects:
            print\(f"  FILLED RECTANGLES \({len\(rects\)}\):"\)
            for r in rects:
                print\(f"    Rect #{r['index']}: \({r['rect'][0]},{r['rect'][1]}\) -> \({r['rect'][2]},{r['rect'][3]}\)"\)
                print\(f"      Size: {r['width']} x {r['height']}  Fill: {r['fill_color']} \(raw={r['fill_raw']}\)  Stroke: {r['stroke_color']}"\)
                txt = get_text_in_rect\(page, r["rect"]\)
                if txt:
                    preview = txt[:400]
                    if len\(txt\) > 400: preview += "..."
                    print\(f"      Text inside:"\)
                    for line in preview.split\("\\n"\)[:15]:
                        print\(f"        | {line}"\)
                else:
                    print\(f"      Text inside: \(empty\)"\)
                print\(\)
        else:
            print\(f"  No filled rects."\)

        blocks = analyze_text_blocks\(page\)
        print\(f"  TEXT BLOCKS \({len\(blocks\)}\):"\)
        for i, b in enumerate\(blocks\):
            print\(f"    Block {i}: bbox={b['bbox']} fonts={b['fonts']} colors={b['text_colors']} sizes={b['sizes']}"\)
            print\(f"      Text: {b['text_preview']}"\)
            print\(\)

        raw_info = analyze_rawdict_extra\(page\)
        if raw_info:
            print\(f"  RAWDICT EXTRA KEYS:"\)
            for info in raw_info:
                print\(f"    {info}"\)

    # Deep dive on first dbdcpybkgen page
    if target_pages:
        pn = target_pages[0]
        page = doc[pn]
        print\("\\n" + "=" * 80\)
        print\(f"DEEP DIVE: PAGE {pn+1} \(dbdcpybkgen\)"\)
        print\("=" * 80\)

        all_drawings = page.get_drawings\(\)
        print\(f"\\nAll drawings: {len\(all_drawings\)}"\)
        for i, d in enumerate\(all_drawings\):
