                      f"items={item_types}"\)

        images = page.get_images\(\)
        print\(f"\\nImages: {len\(images\)}"\)
        for img in images:
            print\(f"  xref={img[0]} size={img[2]}x{img[3]} cs={img[5]}"\)

        print\(f"\\nFull text:"\)
        print\(page.get_text\("text"\)\)

    doc.close\(\)
    print\("\\nDone."\)

if __name__ == "__main__":
    main\(\)
